-- منهج اللغة الإنجليزية للصف الخامس ف١ (Team Together Oman 5A — Class Book).
-- الوحدة كما في الكتاب: Welcome، ثم أربع وحدات لكلٍّ منها عشرة دروس (مفردات، قصة، قواعد، مفردات وقواعد، ثقافة ومشروع،
-- English in action، قراءة، استماع وتحدّث وكتابة، مراجعة، استعداد لاختبار A1 Movers مع Fun corner) ثم قصّتا Graded readers،
-- وأخيراً Bo’s Learning Club. الصفحات بأرقام الكتاب المطبوعة؛ صفحة PDF = المطبوعة + ٢ ← الإزاحة ٣. متعادلة.
delete from public.curriculum where semester='الفصل الأول' and grade=5 and subject='اللغة الإنجليزية';
update public.book_sources set offset_pages=3, updated_at=now() where semester='الفصل الأول' and grade='5' and subject='اللغة الإنجليزية';

-- دليل المعلم (Team Together Oman 5A Teacher's Book): كل درسٍ إلى صفحة ملاحظاته في الدليل.
-- الأرقام صفحات PDF مباشرةً، لذا الإزاحة ١.
update public.teacher_guides tg set offset_pages=1, status='indexed', indexed_at=now(), toc=(
  select jsonb_agg(jsonb_build_object('guide_unit',c.unit,'guide_lesson',c.lesson,'guide_page',v.p,'matched_curriculum_id',c.id,'confidence','high') order by c.sort)
  from public.curriculum c join (values
    (1,27),(2,30),(3,33),
    (4,38),(5,41),(6,44),(7,47),(8,50),(9,53),(10,56),(11,58),(12,61),(13,64),(14,68),(15,71),
    (16,76),(17,79),(18,82),(19,85),(20,88),(21,91),(22,94),(23,96),(24,99),(25,102),(26,106),(27,109),
    (28,114),(29,117),(30,120),(31,123),(32,126),(33,129),(34,132),(35,135),(36,138),(37,141),(38,144),(39,147),
    (40,152),(41,155),(42,158),(43,161),(44,164),(45,167),(46,170),(47,172),(48,175),(49,178),(50,182),(51,185),
    (52,188),(53,192),(54,194)) v(s,p) on v.s=c.sort
  where c.semester='الفصل الأول' and c.grade=5 and c.subject='اللغة الإنجليزية')
where tg.semester='الفصل الأول' and tg.grade=5 and tg.subject='اللغة الإنجليزية';
